impl WwiseObject {
    /// Returns the object GUID string (`id`), if present in the response.
    pub fn id(&self) -> Option<&str> {
        self.id.as_deref()
    }

    /// Returns the object name (`name`), if present in the response.
    pub fn name(&self) -> Option<&str> {
        self.name.as_deref()
    }

    /// Returns the typed [`ObjectType`] (`type`), if present in the response.
    pub fn object_type(&self) -> Option<ObjectType> {
        self.object_type
    }

    /// Returns the object project path (`path`), if present in the response.
    pub fn path(&self) -> Option<&str> {
        self.path.as_deref()
    }

    /// Returns the object notes (`notes`), if present in the response.
    pub fn notes(&self) -> Option<&str> {
        self.notes.as_deref()
    }

    /// Look up a property value in `extra` (checks `"@Property"` first, then `"Property"`).
    pub fn property(&self, prop: Property) -> Option<&serde_json::Value> {
        self.extra
            .get(prop.as_at_str())
            .or_else(|| self.extra.get(prop.as_str()))
    }

    /// Look up a numeric (`f64`) property value in `extra`.
    pub fn property_f64(&self, prop: Property) -> Option<f64> {
        self.property(prop).and_then(serde_json::Value::as_f64)
    }

    /// Look up an integer (`i64`) property value in `extra`.
    pub fn property_i64(&self, prop: Property) -> Option<i64> {
        self.property(prop).and_then(serde_json::Value::as_i64)
    }

    /// Look up a boolean (`bool`) property value in `extra`.
    pub fn property_bool(&self, prop: Property) -> Option<bool> {
        self.property(prop).and_then(serde_json::Value::as_bool)
    }

    /// Look up a string (`&str`) property value in `extra`.
    pub fn property_str(&self, prop: Property) -> Option<&str> {
        self.property(prop).and_then(serde_json::Value::as_str)
    }
}

/// A lightweight object reference returned inside other objects.
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct WwiseObjectRef {
    /// Object ID (GUID).
    #[serde(default, rename = "id")]
    pub id: Option<String>,
    /// Object name.
    #[serde(default)]
    pub name: Option<String>,
}

impl WwiseObjectRef {
    /// Returns the object GUID string (`id`), if present in the response.
    pub fn id(&self) -> Option<&str> {
        self.id.as_deref()
    }

    /// Returns the object name (`name`), if present in the response.
    pub fn name(&self) -> Option<&str> {
        self.name.as_deref()
    }
}

/// Argument to the `from` field of `object.get`.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub enum ObjectQuery {
    /// An array of object IDs, either GUID or Short ID (uint32).
    #[serde(rename = "id")]
    Id(Vec<serde_json::Value>),
    /// An array of text tokens used for searching the project.
    #[serde(rename = "search")]
    Search(Vec<String>),
    /// An array of unique object qualified names.
    #[serde(rename = "name")]
    Name(Vec<String>),
    /// An array of object paths.
    #[serde(rename = "path")]
    Path(Vec<String>),
    /// An array of object types.
    #[serde(rename = "ofType")]
    OfType(Vec<ObjectType>),
    /// An array of query object ID.
    #[serde(rename = "query")]
    Query(Vec<String>),
}

impl ObjectQuery {
    /// Query a single object by GUID or Short ID.
    pub fn id(id: impl Into<String>) -> Self {
        ObjectQuery::Id(vec![serde_json::Value::String(id.into())])
    }

    /// Query multiple objects by GUID strings.
    pub fn ids<I, S>(ids: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        ObjectQuery::Id(
            ids.into_iter()
                .map(|s| serde_json::Value::String(s.into()))
                .collect(),
        )
    }

    /// Query a single object by backslash-separated hierarchy path.
    pub fn path(path: impl Into<String>) -> Self {
        ObjectQuery::Path(vec![path.into()])
    }

    /// Query multiple objects by backslash-separated hierarchy paths.
    pub fn paths<I, S>(paths: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        ObjectQuery::Path(paths.into_iter().map(Into::into).collect())
    }

    /// Query a single object by unique qualified name (`Type:Name`).
    pub fn name(name: impl Into<String>) -> Self {
        ObjectQuery::Name(vec![name.into()])
    }

    /// Query multiple objects by unique qualified names (`Type:Name`).
    pub fn names<I, S>(names: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        ObjectQuery::Name(names.into_iter().map(Into::into).collect())
    }

    /// Search objects by name or notes text.
    pub fn search(text: impl Into<String>) -> Self {
        ObjectQuery::Search(vec![text.into()])
    }

    /// Query all objects of a single [`ObjectType`].
    pub fn of_type(object_type: ObjectType) -> Self {
        ObjectQuery::OfType(vec![object_type])
    }

    /// Query all objects matching any of the given [`ObjectType`] values.
    pub fn of_types(object_types: impl IntoIterator<Item = ObjectType>) -> Self {
        ObjectQuery::OfType(object_types.into_iter().collect())
    }

    /// Run a saved Wwise Query object by GUID.
    pub fn query(guid: impl Into<String>) -> Self {
        ObjectQuery::Query(vec![guid.into()])
    }
}

impl From<String> for ObjectQuery {
    fn from(s: String) -> Self {
        if s.starts_with('{') && s.ends_with('}') {
            ObjectQuery::Id(vec![serde_json::Value::String(s)])
        } else if s.starts_with('\\') {
            ObjectQuery::Path(vec![s])
        } else if s.contains(':') {
            ObjectQuery::Name(vec![s])
        } else {
            ObjectQuery::Path(vec![s])
        }
    }
}
impl From<&str> for ObjectQuery {
    fn from(s: &str) -> Self {
        Self::from(s.to_string())
    }
}
impl From<&String> for ObjectQuery {
    fn from(s: &String) -> Self {
        Self::from(s.as_str())
    }
}
impl From<Vec<String>> for ObjectQuery {
    fn from(v: Vec<String>) -> Self {
        ObjectQuery::Id(v.into_iter().map(serde_json::Value::String).collect())
    }
}
impl From<ObjectType> for ObjectQuery {
    fn from(object_type: ObjectType) -> Self {
        ObjectQuery::OfType(vec![object_type])
    }
}
impl From<Vec<ObjectType>> for ObjectQuery {
    fn from(object_types: Vec<ObjectType>) -> Self {
        ObjectQuery::OfType(object_types)
    }
}

/// Selector for an `object.get` select transformation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum TransformSelect {
    /// `parent`.
    #[serde(rename = "parent")]
    Parent,
    /// `children`.
    #[serde(rename = "children")]
    Children,
    /// `descendants`.
    #[serde(rename = "descendants")]
    Descendants,
    /// `ancestors`.
    #[serde(rename = "ancestors")]
    Ancestors,
    /// `referencesTo`.
    #[serde(rename = "referencesTo")]
    ReferencesTo,
}

/// A single transformation step in an `object.get` query.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub enum Transform {
    /// Select related objects (`parent`, `children`, `descendants`, `ancestors`, or `referencesTo`).
    Select {
        /// Selector list (contains a single [`TransformSelect`] element).
        select: Vec<TransformSelect>,
    },
    /// Deduplicate object instances (`"distinct"`).
    Distinct(String),
    /// Slice results by `[from, count]` boundary indexes.
    Range {
        /// Two-element range `[from, count]`.
        range: Vec<usize>,
    },
    /// Filter objects using a `where` predicate and parameter.
    Where {
        /// Predicate name followed by its parameter(s).
        #[serde(rename = "where")]
        where_: Vec<serde_json::Value>,
    },
}

impl Transform {
    /// Select related objects (`parent`, `children`, `descendants`, `ancestors`, or `referencesTo`).
    pub fn select(selector: TransformSelect) -> Self {
        Transform::Select {
            select: vec![selector],
        }
    }

    /// Deduplicate the current object list (`"distinct"`).
    pub fn distinct() -> Self {
        Transform::Distinct("distinct".to_string())
    }

    /// Take a slice of results starting at 0-based `from` with length `count` (`[from, count]`).
    pub fn range(from: usize, count: usize) -> Self {
        Transform::Range {
            range: vec![from, count],
        }
    }

    /// Filter objects whose name contains `substring` (case-insensitive, `["name:contains", substring]`).
    pub fn where_name_contains(substring: impl Into<String>) -> Self {
        Transform::Where {
            where_: vec![
                serde_json::Value::String("name:contains".to_string()),
                serde_json::Value::String(substring.into()),
            ],
        }
    }

    /// Filter objects whose name matches regular expression `regex` (`["name:matches", regex]`).
    pub fn where_name_matches(regex: impl Into<String>) -> Self {
        Transform::Where {
            where_: vec![
                serde_json::Value::String("name:matches".to_string()),
                serde_json::Value::String(regex.into()),
            ],
        }
    }

    /// Filter objects whose type is in `types` (`["type:isIn", [...]]`).
    pub fn where_type_is_in(types: impl IntoIterator<Item = ObjectType>) -> Self {
        let list = types
            .into_iter()
            .map(|t| serde_json::Value::String(t.as_str().to_string()))
            .collect();
        Transform::Where {
            where_: vec![
                serde_json::Value::String("type:isIn".to_string()),
                serde_json::Value::Array(list),
            ],
        }
    }

    /// Filter objects whose category is in `categories` (`["category:isIn", [...]]`).
    pub fn where_category_is_in<I, S>(categories: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        let list = categories
            .into_iter()
            .map(|c| serde_json::Value::String(c.into()))
            .collect();
        Transform::Where {
            where_: vec![
                serde_json::Value::String("category:isIn".to_string()),
                serde_json::Value::Array(list),
            ],
        }
    }
}

impl From<TransformSelect> for Transform {
    fn from(selector: TransformSelect) -> Self {
        Transform::select(selector)
    }
}

